require('dotenv').config();
const TronWeb = require('tronweb');

const tronWeb = new TronWeb.TronWeb({
    fullHost: 'https://api.trongrid.io',
});

const SENDER_PRIVATE_KEY = process.env.TRON_PRIVATE_KEY;

async function main() {
    try {
        const transactionHex = "";
        const transactionDataDeserialized = tronWeb.utils.transaction.DeserializeTransaction('TriggerSmartContract', transactionHex);
        const transactionPb = tronWeb.utils.transaction.txJsonToPb({
            raw_data: transactionDataDeserialized,
        });
        const txID = tronWeb.utils.transaction.txPbToTxID(transactionPb);
        const fullTransaction = {
            txID: txID.replace(/^0x/, ''),
            raw_data: transactionDataDeserialized,
            raw_data_hex: transactionHex
        };
        const signedTransaction = await tronWeb.trx.sign(fullTransaction, SENDER_PRIVATE_KEY);
        const result = await tronWeb.trx.sendRawTransaction(signedTransaction);
        console.log('RESULT', result);
    } catch (error) {
        console.error('ERROR:', error);
    }
}
main();